<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('User/level_gift')}">礼包管理</a>					<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('User/level_gift_add')}','添加礼包',550,400,true,false,false,addbtn,'add',true);" style="margin-left:20px;">添加礼包</a>                    <a href="{pigcms{:U('User/level_gift_order')}"  class="on">礼包领取记录</a>				</ul>			</div>			<table class="search_table" width="100%">				<tr>					<td>						<form action="{pigcms{:U('User/level_gift_order')}" method="get">							<input type="hidden" name="c" value="User"/>							<input type="hidden" name="a" value="level_gift_order"/>                            筛选: <input type="text" name="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>                            <select name="searchtype">                                <option value="order_id" <if condition="$_GET['searchtype'] eq 'order_id'">selected="selected"</if>>订单号</option>                                <option value="get_name" <if condition="$_GET['searchtype'] eq 'get_name'">selected="selected"</if>>客户名称</option>                                <option value="get_phone" <if condition="$_GET['searchtype'] eq 'get_phone'">selected="selected"</if>>客户手机号</option>                                <option value="gift_name" <if condition="$_GET['searchtype'] eq 'gift_name'">selected="selected"</if>>礼包名称</option>                            </select>                            会员等级:                            <select name="level_id" id="level_id" tips="">                                <option value="">全部</option>                                <volist name='user_level' id='vo'>                                    <option value="{pigcms{$vo.id}" <if condition="$_GET['level_id'] eq $vo['id']">selected="selected"</if>>{pigcms{$vo.lname}</option>                                </volist>                            </select>                            状态:                            <select name="status" id="status" tips="">                                <option value="-1" <if condition="$_GET['status'] eq -1">selected="selected"</if>>全部</option>                                <option value="-2" <if condition="$_GET['status'] eq -2">selected="selected"</if>>待领取</option>                                <option value="1" <if condition="$_GET['status'] eq 1">selected="selected"</if>>已领取，待发货</option>                                <option value="2" <if condition="$_GET['status'] eq 2">selected="selected"</if>>已发货</option>                            </select>                            <font color="#000">领取时间日期筛选：</font>                            <input type="text" class="input-text" name="begin_time" style="width:120px;" value="{pigcms{$_GET.begin_time}" onfocus="WdatePicker({readOnly:true,dateFmt:'yyyy-MM-dd'})"/>                            <input type="text" class="input-text" name="end_time" style="width:120px;" value="{pigcms{$_GET.end_time}" onfocus="WdatePicker({readOnly:true,dateFmt:'yyyy-MM-dd'})"/>                            <input type="submit" value="查询" class="button"/>						</form>					</td>				</tr>			</table>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup>							<col/>							<col/>							<col/>							<col/>							<col/>							<col width="180" align="center"/>						</colgroup>						<thead>							<tr>								<th width="50px">订单编号</th>								<th style="max-width: 120px;">客户信息</th>								<th >礼包名称</th>								<th >会员等级</th>                                <th >领取时间</th>                                <th >订单状态</th>								<th>操作</th>							</tr>						</thead>						<tbody>							<if condition="is_array($list)">								<volist name="list" id="vo">									<tr>										<td>{pigcms{$vo.order_id}</td>										<td style="max-width: 120px;">                                            <php>if ($vo['get_name']) {</php>                                            名称： {pigcms{$vo['get_name']}<br/>                                            <php>}</php>                                            <php>if ($vo['get_phone']) {</php>                                            手机号： {pigcms{$vo['get_phone']}<br/>                                            <php>}</php>                                            <php>if ($vo['get_address']) {</php>                                            地址： {pigcms{$vo['get_address']}                                            <php>}</php>                                        </td>                                        <td>{pigcms{$vo.gift_name}</td>                                        <td>{pigcms{$vo.lname}({pigcms{$vo.level})</td>                                        <td>                                            <php>if ($vo['get_time']) {</php>                                                {pigcms{$vo['get_time']|date='Y-m-d H:i:s',###}                                            <php>} else {</php>                                            -                                            <php>}</php>                                        </td>                                        <td>{pigcms{$order_status[$vo['status']]}</td>										<td>                                            <a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('User/level_gift_order_detail',array('order_id'=>$vo['order_id'],\'frame_show\'=>true))}','礼包领取信息',650,500,true,false,false,false,'edit',true);">查看详情</a>                                        </td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="7">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="7">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div><include file="Public:footer"/>